1→//! op-tools: Tool Registry and Execution
//!
//! Provides the tool registry, built-in tools, and HTTP router.
//!
//! ## Security
//!
//! Security is enforced at the ACCESS level, not command level:
//! - **Unrestricted (Admin)**: Full access - can run any command
//! - **Restricted**: Limited read-only access for untrusted users
10→//!
//! The chatbot is designed to be a full system administrator.
//! Rate limiting prevents runaway loops.
//!
//! ## Orchestration Plugin
//!
//! The `orchestration_plugin` module provides hooks for tracking all activity:
//! - Tool executions (commands, file ops, etc.)
//! - LLM decisions and tool calls
//! - Session lifecycle events
20→//!
//! This integrates with snowball for immutable audit logging.

pub mod builtin;
pub mod discovery;
pub mod dynamic_tool;
mod mcptools;
pub mod orchestration_plugin;
pub mod registry;
pub mod router;
30→pub mod security;
pub mod tool;
pub mod validation;

use tracing::warn;

// Re-export main types
pub use orchestration_plugin::{
    LlmDecisionEvent, OrchestrationActivityPlugin, OrchestrationPluginRegistry, SessionEvent,
    ToolExecutedEvent, create_tool_event, get_orchestration_registry,
40→};

// Re-export code_search module (feature-gated in consuming crates)
pub use builtin::code_search;

pub use registry::ToolRegistry;
pub use router::{ToolsServiceRouter, ToolsState, create_router};
pub use security::{
    AccessLevel, SecurityError, SecurityValidator, ToolSecurityProfile, get_security_validator,
};
50→pub use tool::{BoxedTool, Tool};
pub use validation::{InputValidator, ValidatedInput, ValidationConfig};

/// Public error type for tool registry operations.
///
/// Uses `thiserror` per AGENTS.md coding standards.  This keeps `anyhow`
/// out of the public API while preserving ergonomic `?` propagation
/// inside the crate.
#[derive(Debug, thiserror::Error)]
pub enum ToolsError {
60→    #[error("tool registration failed: {0}")]
    Registration(String),
}

impl From<anyhow::Error> for ToolsError {
    fn from(e: anyhow::Error) -> Self {
        Self::Registration(e.to_string())
    }
}

70→/// Register all built-in tools.
///
/// Returns a strongly-typed [`ToolsError`] rather than leaking `anyhow`
/// into the public API surface.
pub async fn register_builtin_tools(
    registry: &ToolRegistry,
) -> std::result::Result<(), ToolsError> {
    builtin::register_all_builtin_tools(registry).await?;
    builtin::register_response_tools(registry).await?;
    if let Err(err) = mcptools::register_mcp_tools(registry).await {
80→        warn!("Failed to register MCP tools: {}", err);
    }
    Ok(())
}

1→//! Tools Router - HTTP endpoints for tool management
//!
//! This module exports a router that can be mounted by op-http.

use axum::{
    Json, Router,
    extract::State,
    http::StatusCode,
    response::IntoResponse,
10→    routing::{get, post},
};
use simd_json::{OwnedValue as Value, json};
use std::sync::Arc;

use crate::registry::ToolRegistry;

/// Tools service state
#[derive(Clone)]
pub struct ToolsState {
20→    pub registry: Arc<ToolRegistry>,
}

impl ToolsState {
    pub fn new(registry: Arc<ToolRegistry>) -> Self {
        Self { registry }
    }
}

/// Create the tools router
30→///
/// Mount this at `/api/tools` in the unified server:
/// ```ignore
/// use op_http::prelude::*;
/// use op_tools::router::{create_router, ToolsState};
///
/// let registry = Arc::new(ToolRegistry::new());
/// let state = ToolsState::new(registry);
/// let router = RouterBuilder::new()
///     .nest("/api/tools", "tools", create_router(state))
40→///     .build();
/// ```
pub fn create_router(state: ToolsState) -> Router {
    Router::new()
        .route("/", get(list_tools_handler))
        .route("/health", get(health_handler))
        .route("/:name", get(get_tool_handler))
        .route("/:name/execute", post(execute_tool_handler))
        .with_state(state)
}
50→
/// Service info for op-http ServiceRouter trait
pub struct ToolsServiceRouter;

impl op_http::router::ServiceRouter for ToolsServiceRouter {
    fn prefix() -> &'static str {
        "/api/tools"
    }

    fn name() -> &'static str {
60→        "tools"
    }

    fn description() -> &'static str {
        "Tool registry API endpoints"
    }
}

// === Handlers ===

70→async fn health_handler() -> impl IntoResponse {
    Json(json!({
        "status": "healthy",
        "service": "tools"
    }))
}

async fn list_tools_handler(State(state): State<ToolsState>) -> impl IntoResponse {
    let tools = state.registry.list().await;
    let tool_list: Vec<_> = tools
80→        .iter()
        .map(|t| {
            json!({
                "name": t.name,
                "description": t.description
            })
        })
        .collect();

    Json(json!({
90→        "tools": tool_list,
        "count": tool_list.len()
    }))
}

async fn get_tool_handler(
    State(state): State<ToolsState>,
    axum::extract::Path(name): axum::extract::Path<String>,
) -> impl IntoResponse {
    match state.registry.get(&name).await {
100→        Some(tool) => Json(json!({
            "name": tool.name(),
            "description": tool.description(),
            "inputSchema": tool.input_schema()
        })),
        None => Json(json!({ "error": "Tool not found" })),
    }
}

async fn execute_tool_handler(
110→    State(_state): State<ToolsState>,
    axum::extract::Path(_name): axum::extract::Path<String>,
    Json(_params): Json<Value>,
) -> impl IntoResponse {
    (
        StatusCode::FORBIDDEN,
        Json(json!({
            "success": false,
            "error": "direct HTTP tool execution is disabled; use an admitted caller path"
        })),
120→    )
}

