impl DbusDiscoverySource {
    /// Introspect all paths for a service and generate tool definitions
    async fn introspect_service_paths(
        &self,
        service: &str,
        bus_type: &CoreBusType,
    ) -> anyhow::Result<Vec<RegistryToolDefinition>> {
